INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                     (1,1,'sentence','My friend is outside now','我的朋友现在在外面，他第一次来 我去接他一下
My friend is outside now. It’s his first time here, so I’m just going to pick him up','My friend is outside now. It’s his first time here, so I’m just going to pick him up','我的朋友现在在外面，他第一次来，我去接他一下。','用于解释你要暂时离开一下。',NULL,'pick him up,first time here',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                     (1,2,'phrase','So we''ll see. We shall see.','So we''ll see. We shall see.
可以翻译成 我们到时候看吧，我们走着瞧','So we''ll see. We shall see.','我们到时候看吧 / 我们走着瞧。','带一点保留判断的语气。',NULL,'we shall see,we''ll see',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                     (1,3,'phrase','I’m just very focused on…','I’m just very focused on…
= 我现在很专注于……','I’m just very focused on…','我现在很专注于……','后面可接工作、学习、任务等。',NULL,'focused on',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                     (1,4,'vocab','interchange','interchange意思是：
当动词：交换；互换；交替使用
当名词：交流；立交枢纽 / 交通转换站','interchange','交换；互换；交替使用；交流；立交枢纽 / 交通转换站','这个词既可以作动词，也可以作名词。',NULL,'interchange',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                     (1,5,'example','interchange as a verb','These two words are often interchanged. 这两个词经常被互换使用。
You can interchange the labels when new people arrive. 新的人来了以后，你可以把标签换一下。','These two words are often interchanged.
You can interchange the labels when new people arrive.','这两个词经常被互换使用。新的人来了以后，你可以把标签换一下。','interchange 作动词。',NULL,'interchange,verb',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                     (1,6,'chunk','swap them / switch them out','• swap them
• switch them out','swap them
switch them out','把它们换掉','和 interchange 相关的自然替换表达。',NULL,'swap,switch out',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                     (1,7,'example','interchange as a noun','an interchange of ideas 思想交流
a motorway interchange 高速公路立交枢纽','an interchange of ideas
a motorway interchange','思想交流；高速公路立交枢纽','interchange 作名词时的例子。',NULL,'interchange,noun',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                     (1,8,'vocab','hawthorn','hawthorn
山楂','hawthorn','山楂','食物词汇。',NULL,'hawthorn',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                     (1,9,'example','hawthorn is very sour','hawthorn is very sour 山楂非常酸','hawthorn is very sour','山楂非常酸。','描述味道。',NULL,'sour,hawthorn',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                     (1,10,'example','plums or prunes','This is kind of like eating plums or prunes.
• plum = 李子
• prune = 西梅 / 李子干（常指干的）','This is kind of like eating plums or prunes.
plum
prune','这有点像在吃李子或西梅。plum = 李子；prune = 西梅 / 李子干。','用来帮助理解 hawthorn 的味道和口感。',NULL,'plum,prune',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                                   (1,11,'sentence','Last week, we had a lot of food programs...','Last week, we had a lot of food programs, so I was running around like a chicken with my head cut off trying to get everything organized. And tonight is gonna be exactly the same, because we are short-staffed and we have an event that has 115 people coming.','Last week, we had a lot of food programs, so I was running around like a chicken with my head cut off trying to get everything organized. And tonight is gonna be exactly the same, because we are short-staffed and we have an event that has 115 people coming.','上周我们有很多餐饮活动，所以我忙得团团转，想把一切都安排好。今晚估计也一样，因为我们人手不足，而且有一个会来 115 人的活动。','完整场景句。',NULL,'food programs,short-staffed,115 people',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,12,'correction','food programs','food programs
更自然的说法
we had a lot of food events
or
we had a lot of food-related activities','we had a lot of food events
we had a lot of food-related activities','更自然的说法：我们有很多餐饮活动 / 餐饮相关活动。','food programs 在这个语境下不如 food events / food-related activities 自然。',NULL,'food events,food-related activities',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,13,'chunk','run around','run around means:
• 忙来忙去
• 到处跑
• 忙得团团转','run around','忙来忙去；到处跑；忙得团团转','非常常见的口语短语。',NULL,'run around',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,14,'idiom','like a chicken with my head cut off','I was running around like a chicken with my head cut off
means:
我忙得像无头苍蝇一样乱转。
• 直译：像一只被砍了头的鸡
• 意译：像无头苍蝇一样','I was running around like a chicken with my head cut off','我忙得像无头苍蝇一样乱转。','一个非常生动的习语，实际翻译时常意译成“无头苍蝇”。',NULL,'idiom,chicken with my head cut off',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,15,'grammar','trying to get everything organized','trying to get everything organized

be + doing + trying to + verb

• 把一切安排好
• 把所有事情整理妥当','trying to get everything organized','把一切安排好；把所有事情整理妥当','这里可以顺手记 be + doing + trying to + verb 的表达方式。',NULL,'get everything organized',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,16,'vocab','gonna','And tonight is gonna be exactly the same
gonna = going to in speech','And tonight is gonna be exactly the same','今晚也会完全一样。','gonna = going to 的口语形式。',NULL,'gonna,going to',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,17,'vocab','short-staffed','short-staffed means:
• 人手不足
• 缺人','short-staffed','人手不足；缺人','工作场景高频表达。',NULL,'short-staffed',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,18,'correction','115 people coming','we have an event that has 115 people coming
More natural versions would be:
we have an event with 115 people coming
we have an event with 115 attendees
we have 115 people coming to an event tonight','we have an event with 115 people coming
we have an event with 115 attendees
we have 115 people coming to an event tonight','更自然的表达：我们有一个会来 115 人的活动。','更自然的改写。',NULL,'115 attendees',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,19,'chunk','Useful chunks to remember','These are the best chunks to learn from this sentence:
• run around
• like a chicken with my head cut off
• get everything organized
• be exactly the same
• be short-staffed
• have an event coming up
• have 115 people coming','run around
like a chicken with my head cut off
get everything organized
be exactly the same
be short-staffed
have an event coming up
have 115 people coming','值得记忆的表达块','适合背诵和复用。',NULL,'useful chunks',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,20,'sentence','So we have a guest speaker this evening...','So we have a guest speaker this evening. Jamil is his first name, and he''s doing a presentation called What''s the Economy About Anyway? Yeah, so it''s a free event, you just have to book in, and it''s from, I think, 6:30 till 8 o''clock tonight, and they''re going to be in the big room just across.','So we have a guest speaker this evening. Jamil is his first name, and he''s doing a presentation called What''s the Economy About Anyway? It''s a free event, you just have to book in, and they''re going to be in the big room just across.','今晚有一位嘉宾讲者，名字叫 Jamil。他会做一个题为“经济到底是怎么回事？”的演讲。这是个免费活动，你只需要预约登记，他们会在对面那间大房间。','活动介绍整句。',NULL,'guest speaker,book in,presentation',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                                   (1,21,'vocab','guest speaker','guest speaker = 嘉宾讲者 / 特邀演讲者','guest speaker','嘉宾讲者；特邀演讲者','活动、课堂都很常用。','We have a guest speaker today.
Tonight’s guest speaker is from Wellington.','guest speaker',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,22,'phrase','do a presentation','do a presentation = 做一个展示 / 做一个演讲 / 做一个报告','do a presentation','做一个展示；做一个演讲；做一个报告','presentation 场景高频搭配。','She’s doing a presentation on climate change.
He’s doing a presentation called “Introduction to GIS.”','do a presentation',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,23,'phrase','called ...','called … = 叫做…… / 题为……','called ...','叫做……；题为……','介绍标题时常用。','He’s doing a presentation called “Introduction to GIS.”','called,title',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,24,'phrase','What’s the Economy About Anyway?','What’s the Economy About Anyway?
这里 anyway 不是“无论如何”，而是语气词，表示：
• 到底
• 说到底
• 究竟是怎么回事','What’s the Economy About Anyway?','经济到底是怎么回事？','anyway 在这里是语气词，不是“无论如何”。',NULL,'anyway',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,25,'phrase','book in','book in 在这里就是：
预约登记 / 预订一个位置
更自然书面一点可以说：
• You just need to book in.
• You just have to register.','book in
You just need to book in.
You just have to register.','预约登记；预订一个位置','新西兰日常很实用。',NULL,'book in,register',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,26,'phrase','the big room just across','the big room just across = 就在对面那间大房间','the big room just across','就在对面那间大房间','很自然的场地位置表达。',NULL,'big room just across',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,27,'sentence','the maximum number of people we can have in that room','the maximum number of people we can have in that room
那个房间最多能容纳的人数','the maximum number of people we can have in that room','那个房间最多能容纳的人数','描述场地容量。',NULL,'maximum number',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,28,'phrase','show up','So we’ll see if they all show up
show up = 到场；出现；来了','So we’ll see if they all show up
show up','我们到时候看看他们会不会都来；到场；出现；来了','show up 是高频口语短语。',NULL,'show up',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,29,'phrase','I reckon','I reckon means:
• I think
• I guess
• In my opinion
= 我觉得…… / 我估计……','I reckon','我觉得……；我估计……','在新西兰、澳大利亚和非正式英式口语里很常见。','I reckon they will all show up.','I reckon',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,30,'phrase','with everything happening right now','with everything happening right now
This means:
考虑到现在发生的这些事情
or
在目前这种情况下','with everything happening right now','考虑到现在发生的这些事情；在目前这种情况下','表达当前整体情境。','With everything going on right now, people are stressed.
With everything happening at work, I’m really busy.','with everything happening right now',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                                   (1,31,'chunk','Useful chunks to remember','These are the best pieces to copy:
• the maximum number of people
• we can have in that room
• we’ve got 115
• we’ll see if they all show up
• I reckon…
• with everything happening right now','the maximum number of people
we can have in that room
we’ve got 115
we’ll see if they all show up
I reckon…
with everything happening right now','值得记忆的表达块','适合直接背诵复用。',NULL,'useful chunks',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,32,'phrase','a slightly polished version','A slightly polished version 的意思是：一个稍微更润色过的版本','a slightly polished version','一个稍微更润色过的版本','常用于说明“我把句子稍微改自然了一点”。',NULL,'polished version',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,33,'sentence','And that one''s not fully booked yet...','And that one''s not fully booked yet, which I''m shocked. I thought that one would have just been, like, booked down like a week. That one''s only half booked, so still like 70 people.','And that one''s not fully booked yet, which I''m shocked. I thought that one would have just been booked out. That one''s only half booked, so still like 70 people.','那个活动还没完全订满，这让我很惊讶。我本来以为一周前就应该满了。现在只订了一半，大概 70 人。','活动报名场景句。',NULL,'fully booked,half booked',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,34,'vocab','fully booked','fully booked = 订满了 / 满员了','fully booked','订满了；满员了','酒店、课程、活动都常用。',NULL,'fully booked',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,35,'phrase','which I’m shocked by','which I’m shocked by = 这让我很惊讶','which I’m shocked by','这让我很惊讶','表达惊讶。',NULL,'shocked by',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,36,'phrase','I thought that one would’ve already been...','I thought that one would have just been…
更自然说法通常是：
• I thought that one would’ve already been…
• I thought that one would’ve been…','I thought that one would’ve already been...
I thought that one would’ve been...','我本来以为它早就已经……了','更自然的缩略表达。',NULL,'would’ve',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,37,'vocab','booked out','booked out = 订满 / 约满','booked out','订满；约满','和 fully booked 接近。','It was booked out weeks ago.
The event got booked out really quickly.','booked out',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,38,'correction','I forget where he’s originally from','I forget what he’s originally
This part is not complete English. It was probably meant to be:
• I forget where he’s originally from
• I forget what his background is','I forget where he’s originally from.
I forget what his background is.','我忘了他原本是哪里人；我忘了他的背景是什么','原句不完整，这里是更自然的修正。',NULL,'originally from,background',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,39,'phrase','about 10 years apart','about 10 years apart
A very useful expression.
• We’re two years apart.
• They were born five years apart.
• They went there about ten years apart.','We’re two years apart.
They were born five years apart.
They went there about ten years apart.','相差十年左右','表示年龄、经历、时间上的差距。',NULL,'years apart',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,40,'phrase','give someone a tour of...','give someone a tour of…
= show someone around a place
• I gave him a tour of the campus.
• She’s showing them around town.','give someone a tour of...
I gave him a tour of the campus.
She’s showing them around town.','带某人参观……','也可以说 show someone around。',NULL,'tour of,show around',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
