INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                                   (1,51,'sentence','they all have different prompts on them','they all have different prompts on them
different prompts = 不同的提示问题 / 不同的话题引导','they all have different prompts on them','它们上面都有不同的提示问题 / 话题引导','课堂活动说明。',NULL,'prompts',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,52,'sentence','We can kind of do it in two different ways.','We can kind of do it in two different ways.','We can kind of do it in two different ways.','我们大概可以用两种不同的方法来做。','用于说明活动方式。',NULL,'two different ways',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,53,'phrase','pair someone up','pair someone up = 把某人两两分组 / 配对','pair someone up','把某人两两分组；配对','课堂和活动场景高频表达。','I’ll pair you up.
You’ll be paired up with a partner.','pair up',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,54,'phrase','grab a question strip at random','grab a question strip at random = 随机拿一张问题纸条','grab a question strip at random','随机拿一张问题纸条','at random = 随机地。',NULL,'at random',0,0,1,'2026-04-04 16:09:51',1,'2026-04-04 16:09:51'),
                                                                                                                                                                                                                                   (1,55,'vocab','basically','basically = 从基本上说 / 简单来说 / 说白了 / 其实就是','basically','从基本上说；简单来说；说白了；其实就是','非常高频的口语解释词。','Basically, we need to finish this part first.
