                                                                                                                                                                                                                                   (1,93,'phrase','holiday gathering','holiday gathering = 节日聚会','holiday gathering','节日聚会','比 party 更温和自然。','We’re having a holiday gathering this weekend.
It was a small holiday gathering with family and friends.','holiday gathering',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,94,'phrase','Do you need me to bring anything?','Do you need me to bring anything?','Do you need me to bring anything?','需要我带什么东西来吗？','赴约和聚会前很实用。',NULL,'bring anything',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,95,'vocab','ease','ease 可以是：
动词 = 缓解，减轻
名词 = 轻松，舒适','ease','缓解；减轻；轻松；舒适','可以作动词，也可以作名词。','ease the pain
ease the burden
ease tension
with ease
feel at ease','ease',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,96,'phrase','ease the burden','this can help to ease the burden','this can help to ease the burden','这可以帮助减轻负担。','高频搭配。',NULL,'ease the burden',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,97,'phrase','with ease','with ease = 轻松地，毫不费力地','with ease','轻松地；毫不费力地','名词用法。','She passed the exam with ease.','with ease',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,98,'phrase','feel at ease','feel at ease = 感到放松自在','feel at ease','感到放松自在','常见固定搭配。','He made me feel at ease.','feel at ease',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,99,'phrase','all the other details will be in the invitation','all the other details will be in the invitation','all the other details will be in the invitation','其他细节都会写在邀请函里。','发邀请时很实用。',NULL,'invitation,details',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,100,'phrase','in moderation','in moderation = 适量地 / 有节制地','in moderation','适量地；有节制地','饮食、喝酒、运动等场景高频。','Coffee is fine in moderation.
Everything is okay in moderation.
Eat sweets in moderation.','in moderation',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                                   (1,101,'phrase','it works for so many things in life','it works for so many things in life','it works for so many things in life','它适用于生活中的很多事情。','适合总结一个原则适用面很广。',NULL,'works for so many things in life',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,102,'phrase','a game changer','a game changer','a game changer','一个能改变局面的东西 / 巨大的改变','常用于技术、工具、家庭、效率等场景。','Video calling has been a game changer for my family, especially when I lived abroad.','game changer',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,103,'vocab','impact','impact
常见搭配：
have an impact on
make an impact
a major impact
the impacts of …','impact
have an impact on
make an impact
a major impact
the impacts of …','影响','抽象地说影响时常用单数；强调多种具体影响时可用 impacts。',NULL,'impact,make an impact',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,104,'phrase','at my fingertips','at my fingertips = easily available or accessible','at my fingertips','触手可及；很容易获得；了如指掌','既可表示资源触手可及，也可表示对系统很熟悉。','I have all the information at my fingertips.
With the internet, knowledge is at our fingertips.
She has the whole system at her fingertips.','at my fingertips',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,105,'vocab','tragic','tragic = 悲剧的','tragic','悲剧的','基础词汇。',NULL,'tragic',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,106,'phrase','there is plenty of food to go around','there is plenty of food to go around','There is plenty of food to go around.','有很多食物，够大家分。','to go around = 够分给大家 / 足够每个人都有。',NULL,'go around',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,107,'phrase','stay on top of things','to stay on top of things = 把事情都掌控住 / 把事情都安排好 / 跟上所有要处理的事','stay on top of things','把事情都掌控住；安排好；跟上所有要处理的事','工作和生活场景都很常用。',NULL,'stay on top of things',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,108,'sentence','A digital calendar really helps me stay organized...','A digital calendar really helps me stay organized, not be late for things, and know what’s going on.
The calendar helps me stay on top of things at work.','A digital calendar really helps me stay organized, not be late for things, and know what’s going on.
The calendar helps me stay on top of things at work.','数字日历真的能帮助我安排好事情、不迟到，也知道最近发生什么。它能帮助我把工作上的事情都掌控住。','整合后的自然表达。',NULL,'digital calendar,stay organized',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,109,'phrase','not be late','not be late
help 后面通常接：
help someone do something
help someone be something','not be late','不迟到','顺便复习 help 的搭配。',NULL,'not be late',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29'),
                                                                                                                                                                                                                                   (1,110,'phrase','open up','open up
It opened up a whole new world.
Virtual learning opened up a whole new world for me.','open up
It opened up a whole new world.
Virtual learning opened up a whole new world for me.','打开；开启；打开一个全新的世界','非常实用的抽象表达。',NULL,'open up,a whole new world',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
    (1,111,'phrase','back in the day','back in the day = 以前 / 当年 / 从前那时候','back in the day','以前；当年；从前那时候','用于谈过去。','Back in the day, we didn’t have smartphones.
I used to play basketball a lot back in the day.','back in the day',0,0,1,'2026-04-04 16:11:29',1,'2026-04-04 16:11:29');



INSERT INTO everyday_sentence (tag,en,cn,note,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                         ('Transport','Just hop on at the yellow line up front.','就在前面黄色线那里上车。','hop on 很口语，表示“上车”。up front = 在前面。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Campus life','A lot of EAP students have just started, so the buses are pretty full.','很多 EAP 学生刚开学，所以公交车非常满。','pretty full 是很自然的口语表达。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Study','I haven’t sat IELTS, but I’ve been doing the EAP English course at Lincoln.','我没有考雅思，但我在 Lincoln 上 EAP 英语课程。','sit IELTS 在澳新/英式英语里表示“参加雅思考试”。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Plans','After I graduate, I’ll think about staying in New Zealand to work, since I’ll have a three-year work visa.','毕业后我会考虑留在新西兰工作，因为我会有三年的工作签证。','think about doing = 考虑做某事。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Personal story','I came to NZ from China mainly for two reasons. Work back home was crazy and I had no free time, and also, the schooling back home is way too competitive for kids. I just wanted a bit of a different pace.','我来新西兰主要有两个原因：国内工作太忙，没有空闲时间，而且那边的教育对孩子来说太卷了。我只是想要一种稍微不同一点的生活节奏。','back home = 在国内。a different pace = 不同的生活节奏。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Background','I’ve done software engineering for over ten years.','我做软件工程已经十多年了。','很适合自我介绍和面试。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Life in NZ','I’ve been in NZ since June last year, only went back home once.','我从去年六月起就在新西兰，中间只回过一次国。','更自然可说：I’ve only gone back home once。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Shopping','Hey, I’m having a hard time choosing the right type of apple on the self-checkout machine. Could you please help me figure out which one I need?','我在自助结账机器上不知道选哪种苹果，你能帮我一下吗？','也可说：I’m not sure which apple to pick on the self-checkout。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Opinion','His failure was an inevitable result of his laziness.','他的失败是他懒惰的必然结果。','inevitable = 不可避免的。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','That’s a perfect way to put it.','你说得太贴切了 / 这个说法太到位了。','很适合回应别人表达得很准确时使用。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59');
INSERT INTO everyday_sentence (tag,en,cn,note,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                         ('Encouragement','I was exhausted, but I pushed through it.','我累得不行了，但我还是坚持下来了。','push through = 咬牙坚持过去。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Encouragement','It feels pointless now, but it won’t always feel this way.','现在感觉没有意义，但不会一直这样。','安慰别人时很自然。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Opinion','Nothing he says counts.','他说话不算数。','也可理解为“他说的话没分量”。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Direct speech','You think you’re more important than you really are.','你把自己看得太重了。','语气较直接，使用时注意场合。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Social issues','I saw some people on social media copying Indian people. Do you think this behavior is offensive?','我看见有些人在社交媒体上模仿印度人，你认为这种行为是冒犯的吗？','offensive = 冒犯的。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Food','I noticed that many Indian foods are fried.','我注意到很多印度食物都是油炸的。','notice that... 是很常见的观察表达。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work / study','Has the problem been solved?','问题解决了吗？','被动语态，适合工作和学习场景。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Classroom','Do we need to check attendance?','我们今天需要签到吗？','check attendance = 点名 / 签到。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Daily life','If this problem is solved, I’ll come to your place.','如果这个问题解决了，我就去你那儿。','your place = 你家 / 你那儿。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Confidence','Nobody looks down on me for using simple words and short sentences.','没有人因为我用简单的词和短句子而看不起我。','look down on = 看不起。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59');
INSERT INTO everyday_sentence (tag,en,cn,note,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                         ('Daily objects','That thermal carafe is quite a handy thing to have.','那个保温壶真是个很实用的东西。','handy = 方便的、实用的。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Small talk','Anything you are working on?','你最近在忙什么？','更自然完整可说：Are you working on anything at the moment?',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','How did it end?','最后结果怎么样？/ 结局如何？','适合问故事、电影、事件的结局。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','How did it go?','怎么样？/ 进展如何？','比 How was it? 更口语自然。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Interview','Do you have any questions for me?','你还有什么要问我的吗？','面试结尾高频句。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Interview','Where do you see yourself in the next few years?','你未来几年的职业规划是什么？','经典面试题。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Banking','Just to confirm, this won’t affect my online banking, right?','我想确认一下，这个不会影响我的网上银行使用，对吗？','Just to confirm... 很适合礼貌确认信息。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work','I’m taking some time off.','我在休息一段时间 / 我在请假 / 我在放假。','常见变体：I’m taking some time off next week。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work','How long are you off for?','你要休息多久？','be off = 休息 / 不上班。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Invitation','Don’t worry about bringing anything.','什么都不用带。','也可以说：No need to bring anything。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59');
INSERT INTO everyday_sentence (tag,en,cn,note,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                         ('Informal','He let rip at the meeting.','他在会上直接开喷。','let rip 很口语，表示猛烈发泄或开骂。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Workplace','The tape’s run out.','胶带用完了。','run out = 用完。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Workplace','You might be able to be trained to cross, but I’ll start you on easy stuff today.','你以后可能会被培训去做其他岗位的事情，但今天我会先让你做一些简单的事。','start someone on easy stuff 是很自然的带教表达。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Feelings','It’s a lot to take in.','信息量有点大 / 有点难一下子消化。','固定表达，常被误说成 take place。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Opinion','What he said is really insightful.','他说得很有见解。','insightful = 有洞见的。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Study','I’m stuck on my assessment.','我的作业卡住了，不知道该怎么写了。','be stuck on = 卡在某个地方。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','How do you cope with ... ?','你如何应对……？','cope with = 应对、处理。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','I haven’t done this for ages.','我好久没做这个了。','for ages 很口语，表示“很久”。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Advice','Taking the train home is going to be the way to go.','坐火车回家是最好的选择。','the way to go = 最佳选择。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Study / work','Let’s do a deep dive into how this works.','我们深入了解一下这个是如何运作的。','deep dive = 深入研究。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59');
INSERT INTO everyday_sentence (tag,en,cn,note,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                         ('Coding','Retain this section of code and remove all other parts.','保留这块代码，把其他部分都删掉。','retain = 保留。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Small talk','How was your day at work?','你今天工作怎么样？','很自然的日常问候。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work','It was good. I was relieved that my boss let me clock out early, so I was able to go home.','挺好的，我松了一口气，老板让我今天早点打卡，所以我能回家了。','clock out = 下班打卡。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work','I sat in on a meeting with the department head.','我旁听了一场和部门负责人的会议。','sit in on = 旁听、列席。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work','It was a hectic day.','那是忙乱的一天。','hectic = 很忙乱的。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work','I’m still settling into my role.','我还在慢慢适应我的岗位。','settle into = 逐渐适应。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work schedule','We rotate through weekend shifts.','我们周末轮流上班。','rotate through = 轮流做。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Daily life','I could use a nap.','我真想小睡一会儿。','委婉表达“我有点累，需要休息”。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Daily life','I’m worn out after work.','下班后我累坏了。','worn out = 非常疲惫。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Feelings','I’m so over my job.','我对这份工作彻底厌烦了。','be over something = 受够了。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59');
INSERT INTO everyday_sentence (tag,en,cn,note,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                         ('Feedback','Some people’s English might be a little mixed up, but that’s not the case with you.','有些人的英语可能有点乱，但你不是这种情况。','that’s not the case with you 很自然。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','I am just saying the truth.','我只是实话实说。','更自然口语可说：I’m just telling the truth。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Money','He made a fortune in the stock market.','他在股市上赚了大钱。','make a fortune = 赚大钱。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Study','I’m just double-checking the assignment requirements to make sure I haven’t missed anything.','我只是再检查一下作业要求，确保没有漏掉什么。','double-check = 再确认一次。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Small talk','What are you up to this weekend?','你这周末准备干什么？','非常常见的周末寒暄。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Small talk','Not much. Just relaxing.','没什么特别安排，就随便放松一下。','回答周末计划时很好用。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Invitation','Do you want to grab a coffee?','你想喝杯咖啡吗？','grab a coffee = 喝杯咖啡 / 约咖啡。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Agreement','Definitely / So true / Exactly / Yeah, totally / 100%','表示强烈同意：绝对是 / 太对了 / 没错 / 完全同意。','适合口语回应别人。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Goodbye','Catch you later.','回头见 / 等会儿见。','轻松友好的告别语。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Learning advice','Try to get into the habit of speaking English every day.','试着养成每天说英语的习惯。','get into the habit of = 养成……习惯。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59');
INSERT INTO everyday_sentence (tag,en,cn,note,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                         ('Shopping','It’s not a big deal if you choose the wrong category when you check out.','结账时选错商品类别也不是什么大问题。','not a big deal = 没什么大不了。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Home','Dinner will be ready in no time.','饭马上就好。','in no time = 很快、马上。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Goals','I’m on a mission to improve my English fluency.','我正在下定决心提升英语流利度。','be on a mission to... = 下定决心去做。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work schedule','I’ll be working till 1 p.m. / I’m gonna work through till 1.','我会一直工作到下午一点。','work through till... 很口语。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Transport','I’m cycling to work today.','我今天骑自行车上班。','也可说 I’m biking to work today。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Transport','There’s a bike rack over there.','那边有个停放自行车的架子。','bike rack = 自行车架。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Opinion','I know it seems wasteful.','我知道这看起来很浪费。','wasteful = 浪费的。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work schedule','When’s your day off? / What days are you off?','你哪天休息？/ 你哪几天休息？','be off = 休息、不上班。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Appearance','He’s really bulked up since last year.','他从去年开始明显练壮了。','bulk up = 变壮、增肌。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Success','All the hard work paid off.','所有努力都有回报了。','pay off = 得到回报。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59');
INSERT INTO everyday_sentence (tag,en,cn,note,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                         ('Conversation','I’m being sarcastic.','我是在讽刺 / 我在说反话。','sarcastic = 讽刺的。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Habits','Occasionally, I watch movies.','我偶尔看电影。','occasionally = 偶尔。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Presentation','I’ll be brief.','我简单两句。','讲话前非常自然。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Instructions','Please follow the brief / instructions.','请按照任务说明 / 指示来做。','brief 在这里是任务说明。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Encouragement','Lower the bar rather than give up.','与其放弃，不如先降低标准。','很适合激励自己。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Parenting','We should give our child a bit more leeway.','我们应该多给孩子一点自由度 / 宽容一些。','leeway = 余地、自由度。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Feedback','Looks like you’ve got the hang of it pretty well.','看起来你已经挺快上手了。','get the hang of it = 上手、掌握窍门。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Workplace','Sometimes it’s a bit hard to work out which category an item should go in.','有时候不太容易弄明白一个商品该归到哪个类别。','work out = 弄明白。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','Whatever works best for you.','看你怎么方便 / 怎么方便怎么来。','非常实用、自然。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','I haven’t been here for a while.','我有一段时间没来这儿了。','和 I haven’t been here for ages 类似。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59');
INSERT INTO everyday_sentence (tag,en,cn,note,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                         ('Weather','We can get hit by four seasons in a day.','我们可能一天经历四个季节。','新西兰天气话题高频句。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Small talk','Is there anything going on outside?','外面在举行什么活动吗？','going on = 正在发生。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Phone','I haven’t got a lot of battery.','我手机没多少电了。','更自然也可说：I don’t have much battery left。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Service','Is there anything else I can help you with?','还有别的事情我能帮你吗？','服务场景高频句。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Family','I want to be reunited with my family.','我想和家人团聚。','be reunited with = 与……重聚。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','That’s not happening right now.','现在还实现不了 / 现在还不行。','口语里很自然的婉转否定。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','So we’ll see. We shall see.','我们到时候看吧 / 我们走着瞧。','带一点保留判断的语气。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Progress','It’s just this last little bit.','就只剩最后这一点点了。','很适合描述快完成了。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Health','This is good for your digestion.','这个对消化有好处。','digestion = 消化。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Health','This food is high in fiber.','这种食物富含纤维。','high in fiber = 富含纤维。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59');
INSERT INTO everyday_sentence (tag,en,cn,note,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                         ('Classroom','Are we doing our English class over at that table soon?','我们一会儿要在那张桌子上英语课吗？','over at that table = 在那边那张桌子。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('School','The school holidays are coming up.','学校快放假了。','coming up = 快到了。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Classroom','I’ll pair you up.','我会把你们两两分组。','pair someone up = 两两分组。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Classroom','Grab a question strip at random.','随机拿一张问题纸条。','at random = 随机地。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work','I got tied up with a client.','我被客户那边的事情耽搁住了。','get tied up with 多用于工作、客户、会议。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','We have a lot of furniture here now, but we didn’t last week.','我们现在这里有很多家具，但上周没有这么多。','对比现在和过去时很自然。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Conversation','Has he come out here?','他来过这里吗？/ 他来这边了吗？','现在完成时结构。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Time','New Zealand is one hour ahead of Fiji.','新西兰时间比斐济快一个小时。','ahead of = 比……快。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Work','It’s very labor-intensive.','这非常费人工 / 这很劳动密集。','新西兰更常见拼写也可写作 labour-intensive。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Health','Sleep is important for your immune system.','睡眠对免疫系统很重要。','immune system = 免疫系统。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59');
INSERT INTO everyday_sentence (tag,en,cn,note,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                         ('Food / health','This product contains no artificial additives.','这个产品不含人工添加剂。','additives = 添加剂。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Weekend','I’m going to sleep in and not set an alarm.','我打算睡个懒觉，不设闹钟。','sleep in = 睡懒觉。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),
                                                                                                                                         ('Food','Are you going to treat me to a big meal?','你要请我吃大餐吗？','treat someone to... = 请某人吃/喝。',0,0,1,'2026-04-04 09:44:59',1,'2026-04-04 09:44:59'),





INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
    (2,1,'grammar','I want you to think back to when ...','I want you to think back to when ...','I want you to think back to when ...','我想让你回想一下……的时候。','固定句型是 want someone to do something。','I want you to think back to when you first started learning English.','think back to,want someone to do something',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
    (2,2,'phrase','for context','for context','for context','补充一下背景；给你一点背景信息。','常用于口语和写作中补充背景。','For context, I have been in New Zealand for about a year.','for context,background',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
    (2,3,'phrase','As far as freedom is concerned, ...','As far as freedom is concerned, ...','As far as freedom is concerned, ...','就自由而言，……','也可以说 As far as freedom goes 或 When it comes to freedom。','As far as freedom is concerned, New Zealand is a good place to live.','as far as freedom is concerned,when it comes to',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
    (2,4,'phrase','around my neighborhood','around my neighborhood','around my neighborhood','在我家附近；在我住的社区周围。','很自然的地点表达。','There are a lot of parks around my neighborhood.','around my neighborhood,neighborhood',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
    (2,5,'phrase','as long as','as long as','as long as','只要……','最常见意思是“只要……”。','As long as you keep practising, your English will improve.','as long as,condition',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
    (2,6,'phrase','be cautious with / be cautious about','be cautious with / be cautious about','be cautious with / be cautious about','在……方面很谨慎；对……很谨慎。','cautious with + 名词；cautious about + doing / 某件事。','They were very cautious with money. / They were cautious about making a decision.','cautious with,cautious about',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
    (2,7,'sentence','We had a couple of shady characters in our neighborhood.','We had a couple of shady characters in our neighborhood.','We had a couple of shady characters in our neighborhood.','我们社区里有几个可疑的人。','a couple of 是固定搭配；shady characters 指可疑的人。',NULL,'a couple of,shady characters',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
    (2,8,'vocab','sleepover','sleepover','sleepover','在别人家过夜的小聚会。','常见于孩子、青少年之间。','I went to a few sleepovers when I was a kid.','sleepover,stay over',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
    (2,9,'sentence','Get off our property.','Get off our property.','Get off our property.','离开我们的地盘。','说私人地盘、私人区域时很常用。','Get off our property right now.','get off our property,property',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
    (2,10,'phrase','at that point','at that point','at that point','在那个时候；到那个节点；在那个阶段。','比 at that time 更有“发展到某一步”的感觉。','At that point, I did not know what to do.','at that point,stage',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                     (2,11,'phrase','keep them under control / keep things under control','keep them under control / keep things under control','keep them under control / keep things under control','把他们控制住 / 把局面控制住。','under control 是很常见的固定搭配。','We need to keep the situation under control.','under control,keep things under control',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,12,'phrase','talk to someone on the phone','talk to someone on the phone','talk to someone on the phone','通过电话跟某人说话。','也可以说 be on the phone with someone。','I am just talking to her on the phone.','on the phone,talk to someone on the phone',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,13,'phrase','boundaries around TV / rules around TV / limits on TV time','boundaries around TV / rules around TV / limits on TV time','boundaries around TV / rules around TV / limits on TV time','在看电视这件事上的界限、规定、限制。','讨论育儿或家庭规则时很常用。','We have some rules around TV. / We have limits on TV time.','rules around TV,limits on TV time',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,14,'phrase','feel peer pressure','feel peer pressure','feel peer pressure','感受到同伴压力。','peer pressure = 同伴压力。','Teenagers often feel peer pressure.','peer pressure,feel peer pressure',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,15,'phrase','in this way / by this standard / in a standard way','in this way / by this standard / in a standard way','in this way / by this standard / in a standard way','用这种方式；按这个标准来说；用一种标准的方式。','这三个表达都自然，但意思不同。','In this way, children can learn more naturally. / By this standard, the result is quite good.','in this way,by this standard,in a standard way',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,16,'vocab','spank someone','spank someone','spank someone','打某人的屁股。','通常指惩罚孩子时打屁股。','Some people think you should never spank children.','spank,discipline',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,17,'phrase','beat someone up','beat someone up','beat someone up','把某人打一顿。','和 spank 不同，beat someone up 指揍一顿。','He got beaten up at school.','beat someone up',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,18,'vocab','circumstances','circumstances','circumstances','情况；条件；环境。','更常见的是复数形式 circumstances。','It depends on the circumstances. / Under normal circumstances, I would agree.','circumstances,under the circumstances',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,19,'sentence','What on earth would compel you to do this?','What on earth would compel you to do this?','What on earth would compel you to do this?','到底是什么驱使你这么做？','on earth 加强语气；compel 比 make 更正式。',NULL,'compel,on earth',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,20,'sentence','I do remember distinctly one time my dad was going to spank me and he just started cracking up.','I do remember distinctly one time my dad was going to spank me and he just started cracking up.','I do remember distinctly one time my dad was going to spank me and he just started cracking up.','我确实很清楚地记得，有一次我爸本来要打我屁股，结果他自己突然笑场了。','do remember 是强调；cracking up = 突然大笑起来。',NULL,'do remember,distinctly,crack up',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                     (2,21,'sentence','What did you get grounded for as a child?','What did you get grounded for as a child?','What did you get grounded for as a child?','你小时候通常因为什么被罚禁足？','get grounded for something 是固定搭配。','I got grounded for lying.','grounded,get grounded for',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,22,'phrase','a common discipline tactic','a common discipline tactic','a common discipline tactic','一种很常见的管教方法 / 管教手段。','适合谈论育儿、教育和家庭管教。','That was a common discipline tactic.','discipline tactic,parenting tactic',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,23,'phrase','take certain things away','take certain things away','take certain things away','把某些东西拿走；收走某些东西作为惩罚。','常见于育儿、处罚、限制 privileges 的场景。','My parents used to take my phone away.','take away,privileges',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,24,'sentence','I feel like I remember getting really defiant.','I feel like I remember getting really defiant.','I feel like I remember getting really defiant.','我感觉我记得自己当时变得特别叛逆 / 特别不服管。','defiant 带明显反抗、不服、对着干的感觉。',NULL,'defiant,rebellious,stubborn',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,25,'vocab','explicit','explicit','explicit','明确的；清楚表达出来的；直白的。','最常见意思是“明确的、明说的”。','He gave me explicit instructions. / You need to be more explicit.','explicit,implicit',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,26,'sentence','I was so sad that I had hit her that I snuck out of my room and into her room, and we started playing with our Barbie dolls.','I was so sad that I had hit her that I snuck out of my room and into her room, and we started playing with our Barbie dolls.','I was so sad that I had hit her that I snuck out of my room and into her room, and we started playing with our Barbie dolls.','我因为打了她而特别难过，于是我偷偷从自己房间跑到她房间，然后我们一起玩芭比娃娃。','had hit 表示先发生；started playing 在这个故事语境里更自然。',NULL,'had hit her,Barbie dolls,snuck into her room',0,0,1,'2026-04-05 06:41:04',1,'2026-04-05 06:41:04'),
                                                                                                                                                                                                                     (2,27,'vocab','casual work','casual work','casual work','临时工作；零工；非固定兼职。','casual work 常见于新西兰和澳洲职场语境，通常指没有固定长期排班、按需要安排的工作。中文可以理解为临时工作、零工、非固定兼职。','casual work','casual work,part-time work',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,28,'vocab','causal','causal','causal','因果的。','causal 是形容词，表示“因果的”。最常见搭配是 a causal relationship，表示因果关系。','a causal relationship = 因果关系','causal,causal relationship',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,29,'sentence','I just wanted to ask for permission before opening it.','就是想在打开前得到您的允许','I just wanted to ask for permission before opening it.','就是想在打开前得到您的允许。','这是一个很礼貌的表达，适合在打开某个物品、文件、包裹、柜子等之前，先征求对方同意。ask for permission = 请求许可。','I just wanted to ask for permission before opening it.','ask for permission,before opening it,permission',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,30,'sentence','Have you seen anything that''s caught your eye?','Have you seen anything that’s caught your eye? Like anything in here, or might be over here somewhere.','Have you seen anything that''s caught your eye? Like anything in here, or might be over here somewhere.','你有看到什么让你眼前一亮的东西吗？比如这边这里的，或者也可能是在那边某个地方的。','caught your eye 是很自然的口语表达，意思是“吸引你的注意”“让你眼前一亮”。很适合购物、逛店、看展品时使用。','Have you seen anything that''s caught your eye? Like anything in here, or might be over here somewhere.','caught your eye,shopping,notice',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                     (2,31,'sentence','Looks pretty good. You found some stuff out.','Thanks, Jesper. Looks pretty good. You found some stuff out.','Thanks, Jesper. Looks pretty good. You found some stuff out.','你还真发现了一些东西。','find something out = 发现；弄清楚。这里带有“你还真查出来一些内容”的感觉。Looks pretty good 也是很自然的评价。','Thanks, Jesper. Looks pretty good. You found some stuff out.','find out,looks pretty good,stuff',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,32,'sentence','They''re just transferring stuff from one place to another, so that''s why it''s allowed.','They’re just transferring stuff from one place to another, so that’s why it’s allowed','They''re just transferring stuff from one place to another, so that''s why it''s allowed.','他们只是把东西从一个地方转移到另一个地方，所以这是被允许的。','transfer stuff from one place to another 是很自然的表达，意思是把东西从一个地方搬到另一个地方。that''s why it''s allowed = 所以这就是为什么它是被允许的。','They''re just transferring stuff from one place to another, so that''s why it''s allowed.','transfer,from one place to another,allowed',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,33,'sentence','Do you have any idea how much it would be? It doesn''t have a price on the mattress.','Do you have any idea that it doesn''t have a price on the metress, I was wondering how much it would be?','Do you have any idea how much it would be? It doesn''t have a price on the mattress.','我想问一下，这个床垫上没有标价。你知不知道它多少钱？','原始意思是想礼貌询问价格。这里整理成更自然版本：Do you have any idea how much it would be? It doesn''t have a price on the mattress. mattress 注意拼写。','Do you have any idea how much it would be? It doesn''t have a price on the mattress.','mattress,price,how much',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,34,'sentence','We have a lot of furniture here now, but we didn''t last week.','这里有很多家具，但是上周不是','We have a lot of furniture here now, but we didn''t last week.','这里现在有很多家具，但是上周不是。','这个句子适合对比现在和过去。we didn''t last week 省略了 have a lot of furniture here，口语里很自然。','We have a lot of furniture here now, but we didn''t last week.','furniture,now,last week,compare',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,35,'phrase','just chilling','Just chilling','Just chilling.','就随便待着；放松一下；在休息。','非常常见的口语表达，表示没干什么特别的事，就是放松、发呆、待着。','Just chilling.','just chilling,chill,relax',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,36,'vocab','show off','show off','show off','1. 炫耀，显摆。2. 展示。','show off 既可以表示“炫耀、显摆”，也可以表示“展示某物给别人看”。要根据语境判断是褒义还是贬义。','He likes to show off. / She wanted to show off her new dress.','show off,boast,display',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,37,'sentence','How young do you think I am?','How young do you thiank I am ?','How young do you think I am?','你认为我有多年轻？','这是自然的口语问句。这里保留了原始问法，并把 thiank 修正为 think。','How young do you think I am?','How young do you think I am',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,38,'sentence','I was studying for a bit.','我只学了一阵子','I was studying for a bit.','我只学了一阵子。','for a bit = 一小会儿；一阵子。口语里非常常见。','I was studying for a bit.','for a bit,study',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,39,'sentence','Pretty lucky to be here.','能在这里已经挺幸运了','Pretty lucky to be here.','能在这里已经挺幸运了。','口语里很自然，省略了 I''m，完整写法可以是 I''m pretty lucky to be here.','Pretty lucky to be here.','pretty lucky,to be here',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,40,'vocab','bench','bench','bench','1. 长凳。2. 工作台。3. 替补席。4. 法官席。','bench 是多义词。最常见是长凳。体育里可以指替补席，法律语境里 the bench 指法官席，工作或木工语境里可以指工作台。','a park bench = 公园长椅；a wooden bench = 木凳 / 长凳；workbench = 工作台；He started on the bench. = 他一开始在替补席上。','bench,workbench,substitute bench',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                     (2,41,'sentence','Do you want to help Tomas at the till?','你想帮助Tomas 收银吗？','Do you want to help Tomas at the till?','你想帮助 Tomas 收银吗？','at the till / on the till / at the register 都能用于收银场景。with the checkout 也自然。','Do you want to help Tomas at the till? / Do you want to help Tomas with the checkout? / Do you want to help me and Tomas at the register?','till,register,checkout',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,42,'phrase','get rid of it','get rid of it','get rid of it','把它弄掉；把它去掉；把它处理掉。','很常见的口语短语，意思可以根据语境变化：去除、扔掉、处理。','get rid of it','get rid of it,remove,throw away',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,43,'phrase','out in the back of Oxford','out in the back of Oxford','out in the back of Oxford','就在 Oxford 后面那一片。','这里有一种“在更后面、更外面那片区域”的感觉。','out in the back of Oxford','back of Oxford,out in the back',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,44,'phrase','good haircut place','good haircut place','good haircut place','很好的理发的地方。','口语里能懂。更自然也可说 a good place to get a haircut。','good haircut place','haircut place,get a haircut',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,45,'sentence','There''s lots of housing going on.','there’s lots of housing going on','There''s lots of housing going on.','那边正在搞很多住宅建设；那边最近住房建设很多。','housing 在这里指住房建设、住宅开发。going on 表示“正在进行”。','There''s lots of housing going on.','housing,housing development,going on',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,46,'vocab','house / housing / household','house / housing / household','house / housing / household','house = 房子；housing = 住房 / 住宅；household = 家庭 / 一户人家。','house 既可作名词，也可作动词，表示给……提供住房、容纳、收藏。housing 常表示住宅、住房、住房开发。household 表示家庭。','This is my house. / The building houses 200 students. / The museum houses many old paintings.','house,housing,household',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,47,'vocab','ankle biters / affection','ankle biters / affection','ankle biters / affection','ankle biters = 小孩子 / 小不点；affection = 喜爱；关爱；疼爱。','ankle biters 是带一点玩笑意味、亲切地称呼小孩子。affection 是名词，表示喜爱、关爱。','She showed great affection for her children. / He has a lot of affection for his dog.','ankle biters,affection,children',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,48,'vocab','pastoral','pastoral','pastoral','1. 田园的，乡村牧场的。2. 教牧的，牧灵的。','A & P show = Agricultural and Pastoral show。pastoral 在自然语境里可表示田园、牧场，在教会语境里可表示教牧关怀。','pastoral scenery = 田园风光；pastoral life = 田园生活；pastoral care = 教牧关怀。','pastoral,A and P show,pastoral care',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,49,'vocab','arvo','Arvo - short for afternoon','arvo','afternoon 的简写形式。','新西兰和澳洲英语里很常见，口语感很强。','Arvo = short for afternoon.','arvo,afternoon,NZ English',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,50,'vocab','bach','bach','bach','新西兰英语里的小型度假屋；海边小屋；周末小屋。','类似 holiday home、beach house、weekend cottage。Te Ara 也把 bach 解释为 seaside cottage; beach house; weekend cottage。','We''re going to the bach this weekend. / Their family has a bach by the beach.','bach,holiday home,beach house,NZ English',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                     (2,51,'vocab','abbreviation / abbreviate / abbreviated','abbreviation / abbreviate / abbreviated','abbreviation / abbreviate / abbreviated','abbreviation = 缩写；abbreviate = 动词，缩写；abbreviated = 形容词，缩写的。','abbreviation 是名词，abbreviate 是动词，abbreviated 是形容词。','Dr. is an abbreviation for Doctor. / NZ is an abbreviation for New Zealand. / ASAP is an abbreviation for as soon as possible.','abbreviation,abbreviate,abbreviated',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,52,'vocab','cattle stop / cattle grid','Cattle-stop','cattle stop / cattle grid','铺在路上的金属横杆栅栏，让牛羊通常不敢走过去。','车可以直接开过去，牛羊一般不敢走过去，所以不用每次开门关门。常见于农场道路。','A metal grid covering a ditch so that farm animals such as cattle and sheep cannot pass through.','cattle stop,cattle grid,farm',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,53,'vocab','ditch','ditch','ditch','1. 沟，渠。2. 甩掉，抛弃，丢下。3. 放弃。','ditch 既可以是名词，也可以是动词。口语里动词用法很常见，比如逃学、扔掉旧东西、放弃计划。','a ditch by the road = 路边沟；He ditched school.；She ditched her old phone.；Don''t ditch me.；We decided to ditch the plan.','ditch,ditch school,ditch the plan',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,54,'vocab','chew','chew','chew','1. 咀嚼。2. 嚼口香糖。3. chew on something = 咬着 / 反复想。','chew 是高频词。既可以用于吃东西，也可以用于 chew on an idea，表示反复琢磨一个想法。','Chew your food slowly. / He was chewing gum. / The dog was chewing on a bone. / I need some time to chew on that idea.','chew,chew on,chewing gum',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,55,'vocab','digestion','digestion','digestion','消化。','相关词：digest = 消化（动词）；digestive system = 消化系统；indigestion = 消化不良。','Good digestion is important for health. / This food helps digestion.','digestion,digestive system,indigestion',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,56,'vocab','daylight saving','daylight saving','daylight saving','夏令时。','你这里是和 Fiji / New Zealand 时间差一起学到的。常见问法：What''s the time difference between Fiji and New Zealand?','What''s the time difference between Fiji and New Zealand?','daylight saving,time difference',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,57,'phrase','a thing of ...','thing of','a thing of ...','某种……的东西；……的事物。','固定结构 a thing of + noun。常见搭配很多。','a thing of beauty = 美好的事物；a thing of the past = 过去的东西 / 已经过时的事物；a thing of value = 有价值的东西。','a thing of beauty,a thing of the past,a thing of value',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,58,'vocab','immune system','immune system','immune system','免疫系统。','健康类高频表达。','A strong immune system helps protect your body from disease. / Sleep is important for your immune system.','immune system,health',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,59,'vocab','additives','additives','additives','添加剂。','常见搭配：artificial additives，chemical additives。','This product contains no artificial additives. / chemical additives = 化学添加剂','additives,artificial additives,chemical additives',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38'),
                                                                                                                                                                                                                     (2,60,'vocab','dye','dye（读音 dai）','dye','1. 染料。2. 染色。','dye 可以作名词，也可以作动词。常见于头发、布料、颜色处理场景。','hair dye = 染发剂；fabric dye = 布料染料；to dye your hair = 染头发；to dye fabric = 给布染色。','dye,hair dye,fabric dye',0,0,1,'2026-04-05 07:41:38',1,'2026-04-05 07:41:38');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                     (2,61,'vocab','nuance','nuance','nuance','细微差别；微妙之处。','常用来表示意思上的细微不同、语气上的微妙差别、文化和表达里的细腻变化。','There''s a slight nuance in meaning. / I''m starting to understand the nuances of English. / Tone and nuance are important in communication.','nuance,nuances,tone',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
                                                                                                                                                                                                                     (2,62,'vocab','give in','give in','give in','1. 屈服，让步。2. 提交（但不如 hand in 常见）。','最常见意思是“屈服、让步”。表示交作业时更自然通常说 hand in your homework。','He refused to give in. / In the end, I gave in. / give in your homework / hand in your homework','give in,hand in,submit',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
                                                                                                                                                                                                                     (2,63,'phrase','sneak peek','Let’s take a little sneak peek','Let''s take a little sneak peek.','我们偷偷先看一眼吧。','sneak peek = 抢先看 / 偷偷看一眼 / 先睹为快。sneak 本身有“偷偷地、悄悄地”的感觉。','a sneak peek of the new movie = 新电影的抢先看','sneak peek,sneak',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
                                                                                                                                                                                                                     (2,64,'phrase','running errands','running errands','running errands','跑腿办事；出门办一些杂事。','很常见的生活口语。','I''m running errands this afternoon. / She spent the morning running errands.','running errands,errands',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
                                                                                                                                                                                                                     (2,65,'phrase','beat the crowds','beat the crowds','beat the crowds','赶在人多之前去；避开人群高峰。','出行、购物、景点场景常见。','We left early to beat the crowds. / Let''s go now and beat the crowds.','beat the crowds,crowds',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
                                                                                                                                                                                                                     (2,66,'vocab','catch up with / catch up on','catch up with / catch up on','catch up with / catch up on','catch up with = 和某人叙旧、赶上某人、最终影响到某人；catch up on = 补上、补做、补看、补听、补学。','这两个短语都非常常用，但对象不同：with 后常接人；on 后常接事情。','I''m catching up with a friend this weekend. / He walks fast, so it''s hard to catch up with him. / Lack of sleep is catching up with me. / I need to catch up on my homework. / I spent the weekend catching up on sleep.','catch up with,catch up on',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
                                                                                                                                                                                                                     (2,67,'sentence','I''m catching a matinee movie on Saturday.','I''m catching a matinee movie on Saturday','I''m catching a matinee movie on Saturday.','我周六要去看一场日场电影。','matinee 指日场演出、午场电影、白天场次。','I''m catching a matinee movie on Saturday.','matinee,movie',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
                                                                                                                                                                                                                     (2,68,'vocab','binge / binge-watch','binge / binge-watch','binge / binge-watch','暴饮暴食；一口气看很多；放纵式地大量做某事。','这个词通常带一点“过量、一口气、有点失控”的感觉。binge-watch = 狂刷、连看很多集。','He went on a binge. / I binge-watched that series. / She binge-watched TV all weekend. / binge drinking / shopping binge','binge,binge-watch',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
                                                                                                                                                                                                                     (2,69,'sentence','I''m just seeing where the weekend takes me.','I''m just seeing where the weekend takes me.','I''m just seeing where the weekend takes me.','我周末就随缘安排；我先不定计划，看看周末怎么发展。','一种很自然、随性的表达。','I''m just seeing where the weekend takes me.','weekend,takes me,casual plan',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
                                                                                                                                                                                                                     (2,70,'phrase','lunch spot','lunch spot','lunch spot','吃午饭的地方；午餐去处。','spot 在这里就是“地方、去处、小店/地点”的意思。','Do you know a good lunch spot nearby? / This is my favourite lunch spot.','lunch spot,spot',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04');
INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                     (2,71,'phrase','get away for the weekend','get away for the weekend','get away for the weekend','周末出去放松一下；周末短途出逃一下。','很自然的周末放松表达。','I''m going to get away for the weekend and travel out-of-state.','get away for the weekend,weekend getaway',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
                                                                                                                                                                                                                     (2,72,'phrase','do some meal prep','do some meal prep','do some meal prep','做点备餐；提前准备几顿饭。','通常指提前把饭菜准备好，比如切菜、腌肉、分装食物，为后面几天省时间。','I''m going to do some meal prep this Sunday. / I do meal prep for the whole week.','meal prep,do some meal prep',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
