INSERT INTO english_note_item (note_id,item_order,item_type,item_title,raw_text,english_text,chinese_text,explanation,examples,keywords,share_status,priority_order,created_by,created_at,updated_by,updated_at) VALUES
                                                                                                                                                                                                                     (2,81,'vocab','overdose','overdose','overdose','1. 过量服用。2. 过量（名词）。','最常见于药物、毒品、化学物质等过量摄入场景。既可作动词，也可作名词。','He overdosed on painkillers. / drug overdose = 药物/毒品过量 / She was taken to hospital after an overdose.','overdose,drug overdose',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
                                                                                                                                                                                                                     (2,82,'vocab','vegetarian','vegetarian','vegetarian','素食者；素食的。','既可作名词，也可作形容词。通常指不吃肉和鱼，但可能吃鸡蛋和奶制品。和 vegan 不同。','She is a vegetarian. / a vegetarian diet / a vegetarian meal','vegetarian,vegan',0,0,1,'2026-04-05 07:44:04',1,'2026-04-05 07:44:04'),
